/**
 * Model DesignChat
 * Chat-driven design session — the conversation a user has with FlowAI
 * to create/iterate on a design. Phase 1 of the Studio Create Chat
 * rebuild (Image + Video unified front door). Each chat owns 0..N
 * generated designs across 1..N branches. State JSON holds the running
 * collected fields (mode, prompt, size, brandColors, references, etc.)
 * so the agent can resume mid-conversation. See
 * docs/superpowers/specs/2026-04-26-studio-create-chat-design.md
 */
export type DesignChat = $Result.DefaultSelection<Prisma.$DesignChatPayload>
/**
 * Model DesignChatTurn
 * One message in a DesignChat. Role can be user / agent / system.
 * `cards` carries any UI cards the agent emitted that turn (mode picker,
 * reference picker, result, branch_compare, etc.) as a JSON array of
 * typed card specs. `attachments` carries reference images the user
 * uploaded or system templates they picked. branchId scopes the turn
 * to a specific branch within the chat for branched iteration.
 */
export type DesignChatTurn = $Result.DefaultSelection<Prisma.$DesignChatTurnPayload>
